<script setup lang="ts">const route=useRoute(),router=useRouter();const filters=reactive({q:String(route.query.q||''),category:String(route.query.category||''),stock:String(route.query.stock||''),sort:String(route.query.sort||'latest'),page:Number(route.query.page)||1});const debounced=ref(filters.q);watchDebounced(()=>filters.q,v=>debounced.value=v,{debounce:350});watch([debounced,()=>filters.category,()=>filters.stock,()=>filters.sort],()=>filters.page=1);watch(filters,()=>router.replace({query:{q:filters.q||undefined,category:filters.category||undefined,stock:filters.stock||undefined,sort:filters.sort==='latest'?undefined:filters.sort,page:filters.page>1?filters.page:undefined}}));const query=computed(()=>({...filters,q:debounced.value}));const {data,pending,error,refresh}=await useFetch('/api/public/products',{query,transform:(r:any)=>r});const {data:cats}=await useFetch('/api/public/categories',{transform:(r:any)=>r.data});useSeoMeta({title:'Katalog Produk | ProShop',description:'Lihat katalog bantal, guling, dan kasur ProShop beserta harga dan stok terbaru.'})</script>
<template><div class="container-main section"><span class="eyebrow">KATALOG PRODUK</span><h1 class="page-title">Temukan produk yang sesuai kebutuhan.</h1><p class="muted intro">Cari berdasarkan nama atau kode, lalu tanyakan ketersediaannya langsung melalui WhatsApp.</p><div class="catalog"><aside><b>Kategori</b><button :class="{active:!filters.category}" @click="filters.category=''">Semua</button><button v-for="c in cats" :key="c.id" :class="{active:filters.category===c.slug}" @click="filters.category=c.slug">{{c.name}}</button></aside><div><div class="filters"><input v-model="filters.q" class="field" placeholder="Cari nama, SKU, atau deskripsi…"><select v-model="filters.stock" class="field"><option value="">Semua stok</option><option value="available">Tersedia</option><option value="low">Stok menipis</option></select><select v-model="filters.sort" class="field"><option value="latest">Terbaru</option><option value="name_asc">Nama A–Z</option><option value="price_asc">Harga termurah</option><option value="price_desc">Harga tertinggi</option></select></div><div class="chips"><button :class="{active:!filters.category}" @click="filters.category=''">Semua</button><button v-for="c in cats" :key="c.id" :class="{active:filters.category===c.slug}" @click="filters.category=c.slug">{{c.name}}</button></div><div v-if="pending" class="state">Memuat produk…</div><div v-else-if="error" class="state">Gagal memuat katalog. <button @click="refresh()">Coba lagi</button></div><ProductGrid v-else :products="data?.data||[]"/><div v-if="data?.meta.totalPages>1" class="pages"><button class="btn btn-outline" :disabled="filters.page<=1" @click="filters.page--">Sebelumnya</button><span>Halaman {{filters.page}} dari {{data.meta.totalPages}}</span><button class="btn btn-outline" :disabled="filters.page>=data.meta.totalPages" @click="filters.page++">Berikutnya</button></div></div></div></div></template>
<style scoped>.intro{max-width:620px;margin-bottom:2.5rem}.catalog{display:grid;grid-template-columns:180px 1fr;gap:2.5rem}aside{display:flex;flex-direction:column;align-items:stretch;gap:.4rem}aside b{margin-bottom:.6rem}aside button,.chips button{border:0;background:none;text-align:left;padding:.65rem;border-radius:8px;color:var(--muted)}aside button.active,.chips button.active{background:var(--gold-pale);color:var(--gold-dark);font-weight:700}.filters{display:grid;grid-template-columns:1fr 180px 180px;gap:.75rem;margin-bottom:1.3rem}.chips{display:none;overflow:auto;gap:.5rem;margin-bottom:1rem}.chips button{white-space:nowrap;border:1px solid var(--border)}.state{padding:4rem;text-align:center}.pages{display:flex;justify-content:center;align-items:center;gap:1rem;margin-top:2rem;font-size:.85rem}@media(max-width:800px){.catalog{display:block}aside{display:none}.chips{display:flex}.filters{grid-template-columns:1fr 1fr}.filters input{grid-column:1/-1}}@media(max-width:480px){.filters{grid-template-columns:1fr}.filters input{grid-column:auto}}</style>
